package com.yihe.framework.ehr;

import java.util.*;import java.util.concurrent.*;
import org.springframework.stereotype.Service;import org.springframework.context.annotation.Bean;import org.springframework.beans.factory.annotation.Value;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;

/** A second source-image read for administrative data quality; never a medical sign-off. */
@Service
public class ArchiveOriginalCheckQueue {
 final EhrRepository db;final EhrService ehr;final DigitalWorkerModelClient model;final DigitalWorkerOriginalCheck reader;
 @Value("${ehr.data-mode:real}") String mode;
 public ArchiveOriginalCheckQueue(EhrRepository db,EhrService ehr,DigitalWorkerModelClient model,DigitalWorkerOriginalCheck reader){this.db=db;this.ehr=ehr;this.model=model;this.reader=reader;}
 @Bean(destroyMethod="shutdownNow") public ScheduledExecutorService archiveOriginalCheckExecutor(){ScheduledExecutorService e=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"archive-original-quality");t.setDaemon(true);return t;});e.scheduleWithFixedDelay(this::tick,8,4,TimeUnit.SECONDS);return e;}
 void request(EhrActor a,String report,int revision,String etag,String stamp){db.exec("INSERT INTO a_archive_original_checks(report_id,revision,input_etag,scope_code,data_mode,original_stamp,approved_item_ids,created_at) VALUES(?,?,?,?,?,?,'[]',UTC_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE check_status=IF(original_stamp<>VALUES(original_stamp),'queued',check_status),approved_item_ids=IF(original_stamp<>VALUES(original_stamp),JSON_ARRAY(),approved_item_ids),checks_json=IF(original_stamp<>VALUES(original_stamp),NULL,checks_json),attempt_count=IF(original_stamp<>VALUES(original_stamp),0,attempt_count),retry_after=IF(original_stamp<>VALUES(original_stamp),NULL,retry_after),original_stamp=VALUES(original_stamp)",report,revision,etag,a.scope,a.mode,stamp);}
 Map<String,Object> status(EhrActor a,String report,int revision){return db.one("SELECT check_status state,attempt_count attempts,JSON_LENGTH(approved_item_ids) verifiedItems,error_message error,started_at startedAt,finished_at finishedAt FROM a_archive_original_checks WHERE report_id=? AND revision=? AND scope_code=? AND data_mode=? AND input_etag=?",report,revision,a.scope,a.mode,hex(digest(bytes(ehr.encode(ehr.snapshot(report,revision))))));}
 void tick(){try{if(!Boolean.TRUE.equals(model.status().get("configured")))return;db.exec("UPDATE a_archive_original_checks SET check_status='queued',retry_after=DATE_ADD(finished_at,INTERVAL 2 MINUTE) WHERE data_mode=? AND check_status='completed' AND error_message IS NOT NULL AND attempt_count<3",mode);db.exec("UPDATE a_archive_original_checks SET check_status='queued',error_message='原件复核中断，将自动重试',retry_after=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 30 SECOND) WHERE data_mode=? AND check_status='running' AND started_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 10 MINUTE)",mode);Map<String,Object> row=db.one("SELECT * FROM a_archive_original_checks WHERE data_mode=? AND check_status='queued' AND (retry_after IS NULL OR retry_after<=UTC_TIMESTAMP(6)) ORDER BY created_at LIMIT 1",mode);if(row==null)return;if(db.exec("UPDATE a_archive_original_checks SET check_status='running',attempt_count=attempt_count+1,started_at=UTC_TIMESTAMP(6),error_message=NULL WHERE report_id=? AND revision=? AND input_etag=? AND check_status='queued'",row.get("report_id"),row.get("revision"),row.get("input_etag"))==1)process(row);}catch(Exception error){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Original-quality queue deferred: {}",error.getClass().getSimpleName());}}
 @SuppressWarnings("unchecked") void process(Map<String,Object> row){String report=str(row.get("report_id")),etag=str(row.get("input_etag"));int revision=num(row.get("revision"));EhrActor a=new EhrActor("archive-xiaogu",str(row.get("scope_code")).substring(4),str(row.get("data_mode")),false,false);
  try{
   require(db.count("SELECT COUNT(*) FROM a_archive_automation w JOIN yh_user_reginfo u ON u.user_code=w.requested_by AND u.lock_flag=2 AND CONCAT('org:',u.Org_Code)=w.scope_code WHERE w.report_id=? AND w.revision=? AND w.scope_code=? AND w.data_mode=?",report,revision,a.scope,a.mode)==1,403,"原件复核授权已变化");ehr.rawReport(a,report,revision,false);require(etag.equals(hex(digest(bytes(ehr.encode(ehr.snapshot(report,revision)))))),409,"原件复核输入已变化");
   new DigitalWorkerSettings(db).requireAi(new DigitalWorkerSettings(db).get(a,"archive"));require(Boolean.TRUE.equals(new DigitalWorkerSettings(db).get(a,"archive").get("acceptingTasks")),422,"档案小谷已暂停");
   Map<String,Object> original=reader.sourceBundle(a,report,revision);require(Boolean.TRUE.equals(original.get("available")),422,"当前不能读取原件，原件复核等待恢复");List<Map<String,Object>> pages=(List<Map<String,Object>>)original.get("pages");require(pages!=null&&!pages.isEmpty(),422,"未读取到可核验原件页");
   List<Map<String,Object>> fields=db.all("SELECT i.item_id id,i.original_field_name label,i.result_raw value,i.unit_raw unit,i.reference_range_raw referenceRange,i.abnormal_flag_raw abnormal,e.source_file_id sourceId,e.page_number page FROM a_health_items i JOIN a_report_evidence e ON e.report_id=i.report_id AND e.revision=i.revision AND e.evidence_id=i.primary_evidence_id WHERE i.report_id=? AND i.revision=? ORDER BY e.source_file_id,e.page_number,i.ordinal",report,revision);
   Map<String,Object> entry=new ArchiveAutoService(db,ehr).status(a,report,revision);if(entry!=null){Map<String,Object> quality=(Map<String,Object>)entry.get("quality");List<?> uncertain=(List<?>)quality.get("uncertainItemIds");if(uncertain!=null)fields.removeIf(f->!uncertain.contains(str(f.get("id"))));}
   List<Map<String,Object>> checks=new ArrayList<>();List<String> approved=new ArrayList<>();Object previous=ehr.decode(row.get("checks_json"));if(previous instanceof List)for(Object raw:(List<?>)previous)if(raw instanceof Map&&Boolean.TRUE.equals(((Map<?,?>)raw).get("matched"))){Map<String,Object> value=(Map<String,Object>)raw;checks.add(value);approved.add(str(value.get("id")));}fields.removeIf(f->approved.contains(str(f.get("id"))));List<String> errors=new ArrayList<>();long deadline=System.currentTimeMillis()+360000;
   ExecutorService pool=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"archive-verify-page");t.setDaemon(true);return t;});List<Callable<List<Map<String,Object>>>> calls=new ArrayList<>();
   for(int offset=0;offset<fields.size();offset+=16){final List<Map<String,Object>> batch=new ArrayList<>(fields.subList(offset,Math.min(offset+16,fields.size())));final List<Map<String,Object>> selected=new ArrayList<>();for(Map<String,Object> page:pages)if(batch.stream().anyMatch(f->Objects.equals(f.get("sourceId"),page.get("sourceId"))&&num(f.get("page"))==num(page.get("page"))))selected.add(page);calls.add(()->{Map<String,Object> answer=model.compareOriginal(map("fields",batch,"pages",selected,"knownLabels",batch.stream().map(f->f.get("label")).collect(java.util.stream.Collectors.toList()),"deadline",deadline));Map<String,List<Map<String,Object>>> found=new HashMap<>();for(Object object:(List<?>)answer.get("checks"))if(object instanceof Map){Map<String,Object> value=(Map<String,Object>)object;found.computeIfAbsent(str(value.get("id")),k->new ArrayList<>()).add(value);}List<Map<String,Object>> verified=new ArrayList<>();for(Map<String,Object> field:batch){List<Map<String,Object>> values=found.get(str(field.get("id")));Map<String,Object> value=values!=null&&values.size()==1?values.get(0):null;verified.add(validate(field,value,selected));}return verified;});}
   try{for(Future<List<Map<String,Object>>> future:pool.invokeAll(calls,360,TimeUnit.SECONDS))try{if(future.isCancelled()){errors.add("原件复核超时，保留未核实字段");continue;}checks.addAll(future.get());}catch(Exception error){errors.add("部分原件页复核服务未完成");}}finally{pool.shutdownNow();}
   for(Map<String,Object> check:checks)if(Boolean.TRUE.equals(check.get("matched"))&&!approved.contains(str(check.get("id"))))approved.add(str(check.get("id")));Collections.sort(approved);
   require(etag.equals(hex(digest(bytes(ehr.encode(ehr.snapshot(report,revision))))))&&str(row.get("original_stamp")).equals(new ArchiveQualityService(db,ehr).originalStamp(a,report,revision)),409,"原件复核期间报告或原件已变化");
   boolean retry=!errors.isEmpty()&&num(row.get("attempt_count"))<2;
   db.exec("UPDATE a_archive_original_checks SET check_status=?,approved_item_ids=?,checks_json=?,error_message=?,retry_after=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 2 MINUTE),finished_at=UTC_TIMESTAMP(6) WHERE report_id=? AND revision=? AND input_etag=? AND original_stamp=? AND check_status='running'",retry?"queued":"completed",ehr.encode(approved),ehr.encode(checks),errors.isEmpty()?null:String.join("；",new LinkedHashSet<>(errors)),report,revision,etag,row.get("original_stamp"));db.exec("UPDATE a_archive_automation SET retry_after=NULL WHERE report_id=? AND revision=?",report,revision);ehr.audit(a,null,report,revision,"archive_original_rechecked","档案小谷已再次读取原件，"+approved.size()+"项指标通过模型原件交叉核验；"+(retry?"未完成批次将自动重试；":"")+"未完成医疗签署");
  }catch(Exception error){boolean changed=error instanceof EhrException&&((EhrException)error).status==409&&error.getMessage().contains("变化");db.exec("UPDATE a_archive_original_checks SET check_status=?,error_message=?,retry_after=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 2 MINUTE),finished_at=UTC_TIMESTAMP(6) WHERE report_id=? AND revision=? AND input_etag=?",changed?"cancelled":num(row.get("attempt_count"))>=2?"failed":"queued",changed?"输入已有变化，旧原件复核停止":"原件自动复核暂未完成，将重试或保留异常字段",report,revision,etag);}
 }
 static String norm(Object value){return str(value).replaceAll("[\\s\\u00a0\\u3000]+","").replace('–','-').replace('—','-').replace('－','-');}
 static Map<String,Object> validate(Map<String,Object> field,Map<String,Object> found,List<Map<String,Object>> pages){boolean matched=found!=null&&!str(field.get("value")).trim().isEmpty()&&Objects.equals(field.get("sourceId"),found.get("sourceId"))&&num(field.get("page"))==num(found.get("page"));Map<String,Object> page=found==null?null:pages.stream().filter(p->Objects.equals(p.get("sourceId"),found.get("sourceId"))&&num(p.get("page"))==num(found.get("page"))).findFirst().orElse(null);matched&=page!=null;
  String quote=found==null?"":norm(found.get("quote"));matched&=quote.length()>=2&&quote.length()<=2500&&quote.contains(norm(field.get("label")));
  for(String[] pair:new String[][]{{"value","originalValue"},{"unit","originalUnit"},{"referenceRange","originalRange"},{"abnormal","originalAbnormal"}}){String value=norm(field.get(pair[0])),original=found==null?"":norm(found.get(pair[1]));matched&=value.equals(original);if(!original.isEmpty())matched&=ArchiveQualityService.literalResult(found.get("quote"),str(found.get(pair[1])));}
  if(page!=null&&!page.containsKey("image"))matched&=norm(page.get("text")).contains(quote);
  return map("id",field.get("id"),"matched",matched,"method",page!=null&&page.containsKey("image")?"scan_model_crosscheck":"native_text_crosscheck","sourceId",found==null?null:found.get("sourceId"),"page",found==null?null:found.get("page"),"quote",found==null?null:found.get("quote"),"medicalReviewed",false);
 }
}
